"""S3-006 slice C integration cases (backup role, log, ledger, restore helpers); guarded hosted suite."""
from test_database import check, role, assert_sql, deny, uid, W, A, P, C, E, U
from test_lifecycle import delete_sql


def integration():
    backup = role('sequence_backup')
    runtime = role('sequence_auth_runtime')
    record = "sequence_private.backup_record(jsonb_build_object('kind','backup','objectKey','backups/x.tar.gpg','sha256',repeat('a',64),'sizeBytes',10,'migrationVersion','v','details','{}'::jsonb))"
    check('backup role reads backed-up tables across tenants and nothing technical', backup + assert_sql('(SELECT count(*) FROM public.seq_prospects)=2 AND (SELECT count(*) FROM sequence_private.enrollments)=2 AND (SELECT count(*) FROM sequence_private.deletion_tombstones)=0 AND (SELECT count(*) FROM sequence_meta.migrations)>0') + deny('SELECT count(*) FROM sequence_private.auth_sessions', '42501') + deny('SELECT count(*) FROM sequence_private.login_transactions', '42501') + deny('SELECT count(*) FROM sequence_private.auth_rate_limits', '42501') + deny('SELECT count(*) FROM auth.users', '42501'))
    check('backup role cannot write or run operator functions', backup + deny("INSERT INTO sequence_private.provider_readings(meter,value) VALUES('database_bytes',1)", '42501') + deny("UPDATE public.seq_prospects SET display_name='x'", '42501') + deny("DELETE FROM public.seq_lists", '42501') + deny("SELECT sequence_private.apply_deletion_ledger('[]'::jsonb)", '42501') + deny("SELECT sequence_private.restore_finalize('{}'::jsonb)", '42501') + deny(f"SELECT sequence_private.operator_remove_identity('{U}','{uid(60)}')", '42501') + deny("INSERT INTO sequence_private.backup_log(kind,object_key,sha256,size_bytes,migration_version) VALUES('backup','k',repeat('a',64),1,'v')", '42501') + assert_sql('(SELECT count(*) FROM sequence_private.backup_log)>=0'))
    check('backup identities expose minimal rows and backup record validates', backup + assert_sql("(SELECT count(*) FROM sequence_private.backup_identities())=2 AND (SELECT bool_and(email LIKE '%@example.invalid' AND admitted) FROM sequence_private.backup_identities())") + f'SELECT {record};' + deny("SELECT sequence_private.backup_record(jsonb_build_object('kind','other','objectKey','k','sha256',repeat('a',64),'sizeBytes',1,'migrationVersion','v'))", '22023') + deny("SELECT sequence_private.backup_record(jsonb_build_object('kind','backup','objectKey','k','sha256','short','sizeBytes',1,'migrationVersion','v'))", '23514') + 'RESET ROLE;' + assert_sql("(SELECT count(*) FROM sequence_private.backup_log WHERE kind='backup' AND database_principal=session_user)=1") + 'RESET ROLE;' + role() + deny(f'SELECT {record}', '42501') + 'RESET ROLE;' + runtime + deny('SELECT sequence_private.backup_identities()', '42501'))
    check('recovery state follows the backup log', role() + assert_sql("(public.seq_manage('status','{}'::jsonb)->'recovery'->>'state')='unverified'") + 'RESET ROLE;' + f"INSERT INTO sequence_private.backup_log(kind,object_key,sha256,size_bytes,migration_version,completed_at) VALUES('backup','backups/old.tar.gpg',repeat('b',64),1,'v',now()-interval '25 hours');" + role() + assert_sql("(public.seq_manage('status','{}'::jsonb)->'recovery'->>'state')='degraded' AND (public.seq_manage('status','{}'::jsonb)->>'growthAllowed')::boolean") + 'RESET ROLE;' + f"INSERT INTO sequence_private.backup_log(kind,object_key,sha256,size_bytes,migration_version) VALUES('backup','backups/new.tar.gpg',repeat('c',64),1,'v');" + role() + assert_sql("(public.seq_manage('status','{}'::jsonb)->'recovery'->>'state')='ok' AND (public.seq_manage('status','{}'::jsonb)->'recovery'->>'lastBackupAt') IS NOT NULL"))
    check('deletion records the latest backup cutoff', role() + f"SELECT {delete_sql(uid(99))};" + 'RESET ROLE;' + assert_sql(f"(SELECT backup_cutoff IS NOT NULL AND backup_cutoff=(SELECT max(completed_at) FROM sequence_private.backup_log) FROM sequence_private.deletion_tombstones WHERE workspace_id='{W}')"), f"INSERT INTO sequence_private.backup_log(kind,object_key,sha256,size_bytes,migration_version) VALUES('backup','backups/cut.tar.gpg',repeat('d',64),1,'v');")
    check('ledger application removes a restored workspace and tombstones it', f"SELECT sequence_private.apply_deletion_ledger(jsonb_build_array(jsonb_build_object('workspaceId','{W}','userId','{U}','requestId','{uid(98)}','deletedAt',now()::text)));" + assert_sql(f"NOT EXISTS(SELECT 1 FROM public.seq_workspaces WHERE id='{W}') AND NOT EXISTS(SELECT 1 FROM sequence_private.enrollments WHERE workspace_id='{W}') AND (SELECT NOT active FROM sequence_private.access_allowlist WHERE user_id='{U}') AND EXISTS(SELECT 1 FROM sequence_private.deletion_tombstones WHERE workspace_id='{W}' AND result->>'source'='ledger') AND (SELECT count(*) FROM public.seq_prospects WHERE workspace_id='{uid(2,2)}')=1") + deny("SELECT sequence_private.apply_deletion_ledger('{}'::jsonb)", '22023') + deny("SELECT sequence_private.apply_deletion_ledger('[{\"workspaceId\":null}]'::jsonb)", '22023'))
    check('restore finalize holds every sequence, cancels intent and revokes sessions', f"UPDATE sequence_private.enrollments SET status='Waiting' WHERE id='{E}';" + "SELECT sequence_private.restore_finalize('{}'::jsonb);" + assert_sql(f"(SELECT status='Held' AND stop_reason='restore-reconciliation' FROM sequence_private.enrollments WHERE id='{E}') AND NOT EXISTS(SELECT 1 FROM sequence_private.enrollments WHERE status IN ('Active','Waiting','Paused')) AND NOT EXISTS(SELECT 1 FROM sequence_private.logical_actions WHERE state NOT IN ('Cancelled','ConfirmedSent','MayHaveSent','OutcomeUnknown','Skipped')) AND NOT EXISTS(SELECT 1 FROM sequence_private.auth_sessions WHERE revoked_at IS NULL)") + role() + assert_sql('(SELECT count(*) FROM public.seq_prospects)=0'))
    check('backup role has no dangerous attributes and no worker membership', assert_sql("(SELECT NOT (rolsuper OR rolcreaterole OR rolcreatedb OR rolreplication OR rolbypassrls) FROM pg_roles WHERE rolname='sequence_backup') AND NOT pg_has_role('sequence_backup','sequence_worker','MEMBER') AND NOT pg_has_role('sequence_backup','sequence_auth_runtime','MEMBER') AND NOT pg_has_role('authenticated','sequence_backup','MEMBER')"))
